"""Generate submission figures and a concise report from actual mission data."""
from pathlib import Path
import csv,hashlib,json,os
os.environ.setdefault('MPLCONFIGDIR','/tmp/volley-mpl-config');os.environ.setdefault('XDG_CACHE_HOME','/tmp/volley-xdg-cache')
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

H=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    inputs=json.loads((H/'MISSION_INPUTS.json').read_text());targets=json.loads((H/'TARGETS.json').read_text());comparison=json.loads((H/'MISSION_COMPARISON.json').read_text());selected=json.loads((H/'SELECTED_CASES.json').read_text())['selected'];native=json.loads((H/'NATIVE_REPLAY_CHECKS.json').read_text());out=H/'figures';out.mkdir(exist_ok=True)
    plt.rcParams.update({'font.size':10,'axes.titlesize':11,'axes.spines.top':False,'axes.spines.right':False,'svg.fonttype':'none','pdf.fonttype':42})
    colors={'gen5':'#2874A6','spring_fixed2':'#D88A1D','spring_pretrim':'#26866B'};labels={'gen5':'Gen5 variable command','spring_fixed2':'Spring fixed 2 m/s','spring_pretrim':'Spring ideal ground pretrim'}
    def save(fig,name):
        for ext in ['png','pdf','svg']:fig.savefig(out/(name+'.'+ext),dpi=190,facecolor='white')
        plt.close(fig)
    fig,axes=plt.subplots(1,2,figsize=(12,4.8),gridspec_kw={'width_ratios':[1.35,1]});groups=[('uniform_2',1.),('uniform_2',5.),('alternating_1_3',1.),('alternating_1_3',5.)];x=np.arange(4);width=.23
    for j,arch in enumerate(colors):
        vals=[]
        for family,authority in groups:
            row=next(r for r in selected if r['family']==family and r['force_authority_N']==authority and r['architecture']==arch);vals.append(row['fuel_used_kg'])
        positions=x+(j-1)*width;axes[0].bar(positions,[np.nan if v is None else v for v in vals],width,label=labels[arch],color=colors[arch])
        for px,value in zip(positions,vals):
            if value is None:axes[0].scatter(px,.007,marker='x',s=48,color=colors[arch],linewidth=1.8)
    axes[0].set_xticks(x,['Uniform 2\n1 N','Uniform 2\n5 N','Alternating 1/3\n1 N','Alternating 1/3\n5 N']);axes[0].set_ylabel('Host propellant used [kg]');axes[0].set_ylim(0,.325);axes[0].set_title('Best feasible tested finite-burn policy');axes[0].grid(axis='y',alpha=.18);axes[0].legend(fontsize=8,loc='upper left')
    masses=[inputs['mass_basis']['initial_spring_wet_kg'],inputs['mass_basis']['initial_Gen5_wet_kg']];bottom=np.zeros(2)
    for label,value,color in [('Bus dry',np.full(2,480.),'#9EAAB4'),('Propellant',np.full(2,20.),'#A8BFD3'),('12 payloads',np.full(2,48.),'#D2DBE2'),('Retained device',np.array([72.,inputs['mass_basis']['Gen5_total_device_kg']]),'#63539A')]:axes[1].bar([0,1],value,bottom=bottom,width=.55,color=color,label=label);bottom+=value
    axes[1].set_xticks([0,1],['Spring class\nassumption','Corrected Gen5']);axes[1].set_ylabel('Initial wet mass [kg]');axes[1].set_ylim(0,790);axes[1].set_title('Same 500 kg wet bus + 48 kg payload',pad=40);axes[1].legend(fontsize=8,loc='lower center',bbox_to_anchor=(.5,1.01),ncol=2)
    for i,mass in enumerate(masses):axes[1].text(i,mass+8,f'{mass:.3f} kg',ha='center',fontsize=9)
    axes[0].set_title('Best feasible tested finite-burn policy',pad=40)
    fig.text(.5,.025,'× means no tested candidate met that force ceiling; it is not a global infeasibility result.\nGen5 device = 149.5567 kg CAD + 7 kg allowance; spring device = declared 12 × 6 kg class assumption.',ha='center',fontsize=8,color='#444E59');fig.subplots_adjust(left=.07,right=.98,top=.79,bottom=.22,wspace=.3);save(fig,'MISSION_RESOURCES')
    fig,axes=plt.subplots(1,2,figsize=(12,4.8));family_colors={'uniform_2':'#2874A6','alternating_1_3':'#B65B45'}
    chief=np.array(targets['families']['uniform_2']['host_target']);radial=chief[:3]/np.linalg.norm(chief[:3]);normal=np.cross(chief[:3],chief[3:]);normal/=np.linalg.norm(normal);along=np.cross(normal,radial)
    for name,family in targets['families'].items():
        times=np.array([r['t']for r in family['shots']]);q=np.array([r['q_m_s']for r in family['shots']]);label='Uniform 2 m/s'if name=='uniform_2'else'Alternating 1/3 m/s';axes[0].plot(times/60,q,'o-',color=family_colors[name],label=label)
        delta=np.array([np.array(r['target'][:3])-chief[:3]for r in family['shots']]);T=delta@along/1000;R=delta@radial/1000;axes[1].scatter(T,R,color=family_colors[name],label=label)
        for i,(tx,ry)in enumerate(zip(T,R),1):
            if i in [1,6,12]:axes[1].annotate(str(i),(tx,ry),xytext=(4,4),textcoords='offset points',fontsize=7)
    axes[0].set_xlabel('Release epoch after common start [min]');axes[0].set_ylabel('Synthetic inertial +along-track kick [m/s]');axes[0].set_yticks([1,2,3]);axes[0].set_title('Architecture-independent target construction');axes[0].legend(fontsize=8);axes[0].grid(alpha=.18)
    axes[1].set_xlabel('Along-track offset from chief [km]');axes[1].set_ylabel('Radial offset from chief [km]');axes[1].set_title('Common-epoch target positions in chief RTN');axes[1].grid(alpha=.18)
    fig.text(.5,.025,'12 × 4 kg 3U; releases every 450 s from 450 to 5400 s, within one nominal 500 km SSO orbit.\nFull PV targets are evaluated at 91800 s: 24 h after final release. RTN points are target positions; labels mark selected release indices.',ha='center',fontsize=8,color='#444E59');fig.subplots_adjust(left=.07,right=.98,top=.9,bottom=.22,wspace=.28);save(fig,'MISSION_TARGETS')
    fig,axes=plt.subplots(1,2,figsize=(12,4.4),gridspec_kw={'width_ratios':[1.7,1]});runs=sorted([r for r in native['native_runs']if r['category']!='step_refinement'],key=lambda r:r['name']);tick=[];bars=[]
    for i,row in enumerate(runs):
        name=row['name'];family='U'if name.startswith('uniform')else'A';arch='gen5'if'_gen5_'in name else'spring_fixed2'if'_spring_fixed2_'in name else'spring_pretrim';label=('G5'if arch=='gen5'else'Fixed'if arch=='spring_fixed2'else'Pretrim')+' '+family
        if family=='A'and arch=='spring_pretrim':label+=' 5N'if'shared_narrow'in name else' 1N'
        if row['category'].startswith('diagnostic'):label+=' diag.'
        tick.append(label);bar=axes[0].bar(i,row['max_payload_target_position_error_m']*1e6,color=colors[arch],width=.65)
        if row['category'].startswith('diagnostic'):bar[0].set_hatch('///')
    axes[0].set_xticks(range(len(tick)),tick,rotation=25,ha='right');axes[0].set_ylabel('Maximum payload terminal difference [µm]');axes[0].set_title('Independent Orekit replay vs frozen full-PV targets');axes[0].grid(axis='y',alpha=.18)
    refinements=native['native_step_refinement'];axes[1].bar([0,1],[r['max_terminal_PV_position_change_m']*1e6 for r in refinements],color='#5C7185',width=.55);axes[1].set_xticks([0,1],['Gen5 uniform','Gen5 alternating']);axes[1].set_ylabel('Maximum terminal position change [µm]');axes[1].set_title('Native maximum step: 60 → 30 s');axes[1].grid(axis='y',alpha=.18)
    fig.text(.5,.025,'Numerical agreement in the declared fixed-axis J2 point-release model; these values are not flight delivery accuracy.\nThe hatched fixed-spring alternating case is diagnostic above the declared force ceilings.',ha='center',fontsize=8,color='#444E59');fig.subplots_adjust(left=.075,right=.98,top=.88,bottom=.26,wspace=.3);save(fig,'MISSION_NATIVE_AGREEMENT')
    with(H/'MISSION_RESULTS.csv').open('w')as f:
        w=csv.DictWriter(f,fieldnames=list(selected[0]));w.writeheader();w.writerows(selected)
    maxpos=max(r['max_payload_target_position_error_m']for r in native['native_runs']);maxvel=max(r['max_payload_target_velocity_error_m_s']for r in native['native_runs']);maxmass=max(r['max_independent_mass_flow_residual_kg']for r in native['native_runs']);maxmoment=max(r['max_momentum_residual_kg_m_s']for r in native['native_runs'])
    lines=['# Corrected Gen5: synthetic same-input mission comparison','','The tested Gen5 policy closes the uniform 2 m/s target family with 1 N and 5 N host authority, and the alternating 1/3 m/s family with 5 N. The ideal ground-pretrimmed spring comparator closes both families with either authority. These preplanned cases show no Gen5 propellant or initial wet-mass advantage over that comparator.','','## Common inputs','','Each architecture starts from the same six-state nominal 500 km SSO orbit and carries twelve 4 kg 3U payloads. The first-order J2 SSO inclination is '+f"{targets['first_order_J2_SSO_inclination_deg']:.6f}°"+' and the Kepler period is '+f"{targets['Kepler_period_s']:.6f} s"+'. Releases occur at 450, 900, …, 5400 s; the final release is inside one orbit. All twelve payload targets and the retained host target are evaluated at the same epoch, 91800 s, exactly 24 h after final release.','','The initial wet bus is **500 kg = 480 kg dry + 20 kg propellant**. The 20 kg is included once. Gen5 retains 149.5567197004 kg of computed CAD device mass plus an explicit 7 kg power/control allowance; the spring reference retains a declared 12 × 6 kg = 72 kg class-study mass. The spring number is an assumption, not a vendor quote. Initial wet masses including the 48 kg payload manifest are **704.556720 kg Gen5** and **620.000000 kg spring**, a **84.556720 kg** device penalty for Gen5.','','Both use the same constant-inertial-force host model, Isp 220 s, 20 kg fuel budget, fixed-axis J2 gravity, and 1 N/5 N thrust-authority gates. The host is recovered to the common chief trajectory at one orbital period and coasts to the common evaluation epoch. No later host-state reset is applied.','','## Targets and control policies','','Targets are constructed independently of architecture: coast an unforced chief to each release epoch, add a synthetic +along-track inertial velocity increment to its PV, then propagate that full six-state child PV under J2 to the common evaluation epoch. The two families use 2 m/s for every payload, or alternate 1 and 3 m/s. All target PV values are frozen in `TARGETS.json` before targeting. They are synthetic study cases, not customer requirements.','','![Synthetic targets](figures/MISSION_TARGETS.png)','','The targeter uses two constant-force windows per leg and continuous propellant mass flow. Both architectures retain 5 s zero-force pre-release and 20 s post-release guards. Gen5 additionally reserves a 400 s zero-force loading coast per payload; the declared 355 s mechanism cycle leaves 45 s reserve. Spring has no imposed loading-coast requirement: it may use the same optional short-window policy or wider 35% and 45% windows. Selection reports the lowest-fuel feasible member of this bounded policy set.','','The fixed spring baseline uses a declared 2 m/s relative separation speed. The stronger ideal spring comparator uses a per-payload ground energy table that compensates predictable finite-host recoil. Those speed/energy values are frozen after mission planning and before native replay. Preplanned variable release energy is therefore represented explicitly; no late target change or inflight retasking is simulated.','','Gen5 commands interpolate computed nominal 1/2/3 m/s coupled-shot release data and remain within the supported command range. Its reusable sled is retained. With pre-release total mass `M`, payload `m=4 kg`, sled `s=13.127805767 kg` and computed sled–host release speed `V`, the post-return payload–retained-host separation speed is','','`u_sep = V × (M − m − s) / (M − m)`','','and the payload inertial kick is `V × (M − m − s) / M`. Thus a 3 m/s sled command is not treated as a direct 3 m/s payload kick. Mass and this mapping are recomputed after each host burn and release; host burns supply the remaining velocity needed by the full-PV target. The ideal spring energy is `0.5 × m × (M−m)/M × u_sep²`.','','## Bounded mission results','','| Target family | Authority | Gen5 propellant | Fixed 2 m/s spring | Ideal ground-pretrimmed spring |','|---|---:|---:|---:|---:|']
    for family,authority in groups:
        cells=[]
        for arch in colors:
            row=next(r for r in selected if r['family']==family and r['force_authority_N']==authority and r['architecture']==arch);cells.append('No tested pass'if row['fuel_used_kg']is None else f"{row['fuel_used_kg']:.6f} kg")
        lines.append('| '+('Uniform 2'if family=='uniform_2'else'Alternating 1/3')+f' | {authority:g} N | '+' | '.join(cells)+' |')
    lines += ['', 'All fourteen constructed targeter candidates close the requested full PV states mathematically. Some require force above the declared ceiling: the tested Gen5 alternating policy peaks at 4.204212 N, and the lowest-peak fixed-spring alternating policy requires 7.537264 N. Their failures at lower ceilings are bounded candidate failures, not global infeasibility proofs. The ideal pretrimmed spring can use a wider policy at 1 N and the shared short-window policy at 5 N.','','![Mission resources](figures/MISSION_RESOURCES.png)','','The 84.556720 kg retained-device penalty is separate from propellant consumption. In this fixed 20 kg fuel-budget comparison, the computed fuel differences do not offset it. The study does not establish a unique inflight-retasking benefit, because all targets were known before the ground energy tables were set.','','## Native replay and numerical checks','',f"Nine accepted native Orekit replay cases include both Gen5 60→30 s step refinements and one clearly labeled fixed-spring diagnostic above the force ceiling. Maximum payload target difference is **{maxpos:.9g} m / {maxvel:.9g} m/s**. Independent mass-flow residual is at most **{maxmass:.3g} kg** and momentum residual at release is **{maxmoment:.3g} kg·m/s**. All fourteen candidate continuity, mass, recoil and guard checks pass. Native coast energy and axial angular momentum invariants are checked as well.",'','![Native numerical agreement](figures/MISSION_NATIVE_AGREEMENT.png)','','Native replay uses the verified installed Orekit 13.1.6 and Hipparchus 4.0.3 jars and propagates every host arc from its previous state. Gen5 recoil is recomputed independently in Java from the replayed mass. The ideal pretrimmed spring uses its frozen speed table. The largest Gen5 native terminal-position change under 60→30 s refinement is '+f"{max(r['max_terminal_PV_position_change_m']for r in native['native_step_refinement']):.9g} m"+'. Numerical agreement is not a physical delivery-accuracy claim.','','## Scope and reproduction','','The comparison uses fixed-axis J2 point masses, point-center release, constant inertial resultant force and Isp 220 s. Drag, higher gravity, third bodies, attitude/plume allocation, actual navigation and finite exit geometry are outside this model. These are constructed two-window policies and sampled schedules, not global fuel optima or real-customer delivery cases.','','The old captured mission work is unchanged. Exact copies of its tested target/export/replay sources and software lock are in `provenance/`; this study creates new inputs and outputs. Run `mission_model.py`, then `native_checks.py`, then `report_and_plot.py` using the recorded runtime. `MISSION_INPUTS.json`, `CALIBRATION.json`, `TARGETS.json`, each `release/*.json/.csv`, `SELECTED_CASES.json` and `NATIVE_REPLAY_CHECKS.json` preserve assumptions, commands, full PV states, forces, fuel, guards and numerical checks. The source/runtime hashes and final integrity capture accompany them.','']
    (H/'MISSION_REPORT.md').write_text('\n'.join(lines))
    metadata=dict(source_sha256={name:sha(H/name)for name in ['MISSION_INPUTS.json','TARGETS.json','MISSION_COMPARISON.json','SELECTED_CASES.json','NATIVE_REPLAY_CHECKS.json','report_and_plot.py']},figures={p.name:sha(p)for p in sorted(out.glob('*'))if p.is_file()},scope='Figures derive directly from current targeter/native data; no synthetic software-interface imagery.')
    (H/'FIGURE_SOURCE_CAPTURE.json').write_text(json.dumps(metadata,indent=2)+'\n');print('Report, CSV and3 scientific figures (PNG/PDF/SVG) generated',flush=True)

if __name__=='__main__':main()
